let currentFlushPromise = null
let queued = false
const queue = []
function trackUpdate() {
  if (queued) return false        // 已在队列：只排一次微任务
  queued = true
  if (!currentFlushPromise) {
    currentFlushPromise = Promise.resolve().then(flushJobs)
  }
  return true
}
function enqueue(job) { queue.push(job); trackUpdate() }
function flushJobs() {
  queued = false
  let i = 0
  while (i < queue.length) {      // 执行中 push 的新任务并入本轮
    try { queue[i++]() } catch (e) { console.error(e) }
  }
  queue.length = 0
  currentFlushPromise = null      // 允许下一轮重新起链
}
function nextTick(cb) {
  const p = currentFlushPromise || Promise.resolve()
  return cb ? p.then(cb) : p
}
// 与 Vue 一致：① nextTick 复用 currentFlushPromise 链尾，保证在 flush 完成后执行；
// ② flush 期间新任务被 while 条件自然吞进本轮，等价 flushJobs 的 queue.length 复查。
